import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.CD2m2Tvf.js";const h=JSON.parse('{"title":"Technical Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"11-glossary.md","filePath":"11-glossary.md"}'),o={name:"11-glossary.md"};function s(i,e,l,c,d,g){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="technical-glossary" tabindex="-1">Technical Glossary <a class="header-anchor" href="#technical-glossary" aria-label="Permalink to &quot;Technical Glossary&quot;">​</a></h1><ul><li><strong>Span</strong>: A named, timed operation representing a single unit of work within a trace.</li><li><strong>Trace</strong>: A Directed Acyclic Graph (DAG) of spans representing end-to-end request execution across microservices.</li><li><strong>Critical Path</strong>: The longest sequential chain of dependent operations in a trace DAG that directly dictated total request latency.</li><li><strong>W3C TraceContext</strong>: The standard specification for distributed context propagation via <code>traceparent</code> and <code>tracestate</code> HTTP headers.</li><li><strong>OTLP</strong>: OpenTelemetry Protocol, the vendor-neutral telemetry transport standard over gRPC and HTTP.</li><li><strong>Head Sampling</strong>: A sampling policy evaluated at the initial gateway before request processing occurs.</li><li><strong>Tail Sampling</strong>: A sampling policy evaluated after request completion, retaining traces based on errors or latency anomalies.</li><li><strong>Columnar Storage</strong>: A database architecture storing data by column rather than row, enabling extreme compression and ultra-fast aggregations.</li><li><strong>Clock Skew</strong>: The time divergence between independent physical server clocks across a distributed cluster.</li></ul>',2)])])}const u=t(o,[["render",s]]);export{h as __pageData,u as default};
